create table if not exists stores ( id text primary key, store_code text not null unique, name text not null, legal_name text not null default '', owner_name text not null default '', contact_email text not null default '', phone text not null default '', address text not null default '', status text not null default 'active', joined_at text not null default (datetime('now')), closed_at text, note text not null default '', created_at text not null default (datetime('now')), check (length(store_code) = 3 and store_code glob '[0-9][0-9][0-9]'), check (status in ('active', 'paused', 'closed')) ); create table if not exists profiles ( id text primary key, user_id text not null unique, store_id text references stores(id) on delete set null, origin_store_id text references stores(id) on delete set null, customer_number text unique, name text not null, name_kana text not null default '', birthday text, avatar_url text, role text not null default 'customer', last_visit_at text, favorite_types text not null default '[]', frequent_times text not null default '[]', created_at text not null default (datetime('now')), check (role in ('customer', 'admin', 'operator')), check (customer_number is null or (length(customer_number) = 7 and customer_number glob '[0-9][0-9][0-9][0-9][0-9][0-9][0-9]')), check (json_valid(favorite_types) and json_valid(frequent_times)) ); create table if not exists base_blends ( id text primary key, code text not null unique, name text not null, description text not null default '', public_ingredients text not null default '[]', benefits text not null default '[]', mood_slugs text not null default '[]', color text not null default '#B9A6D8', created_at text not null default (datetime('now')), check (json_valid(public_ingredients) and json_valid(benefits) and json_valid(mood_slugs)) ); create table if not exists base_blend_private_recipes ( id text primary key, base_blend_id text not null references base_blends(id) on delete cascade, internal_ratio text not null, private_note text not null default '', created_at text not null default (datetime('now')) ); create table if not exists essential_oils ( id text primary key, slug text not null unique, name text not null, botanical_name text not null default '', family text not null default '', scent_note text not null default '', scent_profile text not null default '', overview text not null default '', common_uses text not null default '[]', mood_slugs text not null default '[]', blends_well_with text not null default '[]', safety_note text not null default '', color text not null default '#B9A6D8', check (json_valid(common_uses) and json_valid(mood_slugs) and json_valid(blends_well_with)) ); create table if not exists mood_categories ( id text primary key, slug text not null unique, name text not null, description text not null default '', image_url text, color text not null default '#B9A6D8', icon text not null default 'Sparkles' ); create table if not exists brainwave_images ( id text primary key, user_id text not null references profiles(user_id) on delete cascade, r2_key text not null unique, title text not null default '', note text not null default '', measured_at text, created_at text not null default (datetime('now')) ); create table if not exists aroma_records ( id text primary key, user_id text not null references profiles(user_id) on delete cascade, brainwave_image_id text references brainwave_images(id) on delete set null, blend_lot_number text, base_blend_id text references base_blends(id) on delete set null, base_blend_name text, base_blend_volume_ml real, title text not null, subtitle text not null default '', concept text not null default '', mood text not null default '', purpose text not null default '', blend_notes text not null default '', usage_notes text not null default '', caution_notes text not null default '', maker_note text not null default '', total_volume_ml real, product_image_r2_key text, reorder_url text, price integer, volume text, status text not null default 'draft', made_at text not null, created_at text not null default (datetime('now')), updated_at text not null default (datetime('now')), check (status in ('draft', 'published')) ); create table if not exists aroma_ingredients ( id text primary key, aroma_record_id text not null references aroma_records(id) on delete cascade, name text not null, amount text not null, unit text not null, sort_order integer not null default 0, check (unit in ('滴', 'ml', '%', 'uL')) ); create table if not exists hearing_sheets ( id text primary key, aroma_record_id text references aroma_records(id) on delete cascade, user_id text not null references profiles(user_id) on delete cascade, source text not null default '手動入力', response_id text, submitted_at text, name_kana text not null default '', birthday text, purpose_tags text not null default '[]', desired_scent text not null default '', preference_notes text not null default '', health_notes text not null default '', medication_notes text not null default '', safety_flags text not null default '[]', operator_summary text not null default '', created_at text not null default (datetime('now')), check (json_valid(purpose_tags) and json_valid(safety_flags)) ); create table if not exists favorites ( id text primary key, user_id text not null references profiles(user_id) on delete cascade, aroma_record_id text not null references aroma_records(id) on delete cascade, created_at text not null default (datetime('now')), unique (user_id, aroma_record_id) ); create index if not exists idx_profiles_customer_number on profiles(customer_number); create index if not exists idx_profiles_name on profiles(name); create index if not exists idx_profiles_kana on profiles(name_kana); create index if not exists idx_profiles_last_visit on profiles(last_visit_at); create index if not exists idx_profiles_store on profiles(store_id); create index if not exists idx_profiles_origin_store on profiles(origin_store_id);
